struct MF{HANDLE f=INVALID_HANDLE_VALUE,m=nullptr;const unsigned char*p=nullptr;void open(const std::string&x){f=CreateFileA(x.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE)throw std::runtime_error("open "+x);m=CreateFileMappingA(f,nullptr,PAGE_READONLY,0,0,nullptr);if(!m)throw std::runtime_error("map");p=(const unsigned char*)MapViewOfFile(m,FILE_MAP_READ,0,0,0);if(!p)throw std::runtime_error("view");}~MF(){if(p)UnmapViewOfFile(p);if(m)CloseHandle(m);if(f!=INVALID_HANDLE_VALUE)CloseHandle(f);}};
struct Full100{static constexpr int first[7]={0,1,23,276,2300,14950,80730};MF f[6];Codec codec;explicit Full100(const std::string&d){for(int n=0;n<6;n++){std::string p=d+"/tier"+std::to_string(n)+(n?".i16":".f32");f[n].open(p);int*h=(int*)f[n].p;int w=first[n+1]-first[n];if(h[0]!=0x33545341||h[2]!=100||h[3]!=N||h[4]!=5||h[5]!=n||h[6]!=w)throw std::runtime_error("header");}}inline double val(int r,int b,int p,int h,int n)const{r=std::max(0,std::min(100,r));size_t row=size_t(r*2+b)*(N+1)+p;float base=((const float*)(f[0].p+32))[row];if(!n)return base;int w=first[n+1]-first[n];return base+((const int16_t*)(f[n].p+32))[row*w+h-first[n]]/32.;}inline double deckv(uint32_t deck,int r,int b)const{if(!r&&!b)return 0;int n=__builtin_popcount(deck);double sum=0;uint32_t bits=deck;while(bits){int id=__builtin_ctz(bits)+1;bits&=bits-1;sum+=DECK_COEFF[codec.idmap[id]];}return .6*std::min(1.,.7*(r+b)/n)*sum;}inline double leaf(const State&s)const{if(s.terminal())return s.p;int r=100-s.t;return val(r,s.b,s.p,codec.hand(s),s.n)+deckv(s.deck,r,s.b);}};
struct Planner{Full100&M;int depth;struct DK{uint64_t k;unsigned char d;bool operator==(const DK&o)const{return k==o.k&&d==o.d;}};struct DH{size_t operator()(const DK&x)const{return KeyHash{}(x.k^(uint64_t(x.d)*0x9e3779b97f4a7c15ULL));}};std::unordered_map<DK,double,DH>cache;explicit Planner(Full100&m,int d):M(m),depth(d){cache.reserve(1<<16);}double V(const State&s,int d){if(s.terminal())return s.p;if(d==0)return M.leaf(s);DK k{M.codec.key(s),(unsigned char)d};auto it=cache.find(k);if(it!=cache.end())return it->second;double best=-1e300;uint32_t seen=0;for(int a=0;a<=s.n;a++){int c=a?M.codec.idmap[s.h[a-1]]:0;if(seen&(1u<<c))continue;seen|=1u<<c;best=std::max(best,Q(s,a,d));}cache.emplace(k,best);return best;}double landed(State z,int code,int d){z.p=code&4095;if(z.terminal())return z.p;if(!(code&4096)||z.n==5)return V(z,d);int count[23]={},rep[23]={};uint32_t bits=z.deck;while(bits){int bit=__builtin_ctz(bits);bits&=bits-1;int c=M.codec.idmap[bit+1];count[c]++;rep[c]=bit;}int nn=__builtin_popcount(z.deck);long double sum=0;for(int c=1;c<=22;c++)if(count[c]){State y=z;int bit=rep[c];y.h[y.n++]=bit+1;y.deck&=~(1u<<bit);if(!y.deck)y.deck=0x3fffffff;sum+=(long double)count[c]*V(y,d);}return (double)(sum/nn);}double Q(const State&s,int a,int d){State z=s;int id=0;if(a){id=z.h[a-1];for(int j=a;j<z.n;j++)z.h[j-1]=z.h[j];--z.n;}if(id&&CTYPE[id]!=2)return landed(z,CTYPE[id]==3?NEXT[s.p]:LAND[s.p+CVAL[id]+3],d-1);long double sum=0;for(int sm=2;sm<=12;sm++){int ways=6-abs(7-sm),dbl=!s.b&&(sm%2==0),code=id?LAND[s.p+CVAL[id]*sm+3]:ROLL[s.p*11+sm-2];if(ways-dbl){State y=z;y.t=s.t+!s.b;y.b=0;sum+=(ways-dbl)*landed(y,code,d-1);}if(dbl){State y=z;y.t=s.t+1;y.b=1;sum+=landed(y,code,d-1);}}return (double)(sum/36.0L);}int act(const State&root){if(!root.n)return 0;State s=root;s.t=100-std::min(100,100-root.t);cache.clear();double best=-1e300;int ans=0;uint32_t seen=0;for(int a=0;a<=s.n;a++){int c=a?M.codec.idmap[s.h[a-1]]:0;if(seen&(1u<<c))continue;seen|=1u<<c;double x=Q(s,a,depth);if(x>best){best=x;ans=a;}}return ans;}};
